_output\\\":\\\"     1\\\\timport MIPStarRE.QPBT.Combining.Lines\\\\n     2\\\\timport MIPStarRE.QPBT.Combining.OrderedPoints\\\\n     3\\\\timport MIPStarRE.QPBT.Combining.OverlapGap\\\\n     4\\\\timport MIPStarRE.QPBT.Combining.Points.PlacementSupport\\\\n     5\\\\t\\\\n     6\\\\t/-!\\\\n     7\\\\t# Z-point deficits of the evaluated pair-line measurement\\\\n     8\\\\t\\\\n     9\\\\tThe proof of `lem:claim-17-3` bounds, after its Cauchy--Schwarz step, the\\\\n    10\\\\tdeficit of the overlap between the evaluated pair-line measurement and the\\\\n    11\\\\texpanded `Z`-point measurement at the `Z`-point of the sample.\\\\n    12\\\\tThis module derives that deficit from the\\\\n    13\\\\tconsistency of the evaluated pair-line measurement with the completed joint\\\\n    14\\\\tpoint measurement and from the closeness of the joint point measurement to the\\\\n    15\\\\tordered point products. The derivation inserts the joint point measurement\\\\n    16\\\\ton the point side, replaces it by the ordered product whose trailing factor is\\\\n    17\\\\tthe retained point effect, and sums the other factor, at the cost of three\\\\n    18\\\\tsquare roots. The deficit is first bounded over an arbitrary probability\\\\n    19\\\\tlaw on pairs of line-point pairs and then over a product of two restricted\\\\n    20\\\\tline-point laws, whose point marginal is the uniform pair.\\\\n    21\\\\tThe `_at` variants retain arbitrary opposite placements, including Bob at\\\\n    22\\\\t`BBprime` and Alice at `ABdoubleprime`. The original statements are unchanged\\\\n    23\\\\tspecializations; register commutation does not assume symmetry of the state.\\\\n    24\\\\t\\\\n    25\\\\t## References\\\\n    26\\\\t\\\\n    27\\\\tThe Z deficit is the quantity bounded in the proof of `lem:claim-17-3`\\\\n    28\\\\tin `blueprint/src/chapter/ch15_qpbt_combining.tex`, paper\\\\n    29\\\\t`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1204-1239`; the\\\\n    30\\\\tconsistency input is `lem:qld-xz-lines` and the ordered products are those of\\\\n    31\\\\t`lem:qld-4-10`.\\\\n    32\\\\t-/\\\\n    33\\\\t\\\\n    34\\\\topen scoped BigOperators Matrix MatrixOrder ComplexOrder\\\\n    35\\\\t\\\\n    36\\\\tnamespace MIPStarRE.QPBT\\\\n    37\\\\t\\\\n    38\\\\topen MIPStarRE.LDT hiding Measurement\\\\n    39\\\\topen MIPStarRE.Quantum MIPStarRE.QPBT.DistanceCalculus\\\\n    40\\\\t\\\\n    41\\\\tnoncomputable section\\\\n    42\\\\t\\\\n    43\\\\t/-! ## Completed point pairs -/\\\\n    44\\\\t\\\\n    45\\\\t/-- A sum over completed outcome pairs of a function vanishing on both `none`\\\\n    46\\\\tclasses is the sum over the uncompleted pairs. -/\\\\n    47\\\\ttheorem sum_option_prod_eq_of_none {β γ : Type*} [Fintype β] [Fintype γ]\\\\n    48\\\\t    (F : Option β × Option γ → ℝ) (h1 : ∀ o2, F (none, o2) = 0)\\\\n    49\\\\t    (h2 : ∀ o1, F (o1, none) = 0) :\\\\n    50\\\\t    (∑ o, F o) = ∑ bc : β × γ, F (some bc.1, some bc.2) := by\\\\n    51\\\\t  calc (∑ o : Option β × Option γ, F o)\\\\n    52\\\\t      = ∑ o1 : Option β, ∑ o2 : Option γ, F (o1, o2) := Fintype.sum_prod_type (f := F)\\\\n    53\\\\t    _ = (∑ o2 : Option γ, F (none, o2)) +\\\\n    54\\\\t          ∑ b : β, ∑ o2 : Option γ, F (some b, o2) := Fintype.sum_option _\\\\n    55\\\\t    _ = ∑ b : β, ∑ o2 : Option γ, F (some b, o2) := by\\\\n    56\\\\t        rw [Finset.sum_eq_zero fun o2 _ => h1 o2, zero_add]\\\\n    57\\\\t    _ = ∑ b : β, (F (some b, none) + ∑ c : γ, F (some b, some c)) :=\\\\n    58\\\\t        Finset.sum_congr rfl fun b _ => Fintype.sum_option _\\\\n    59\\\\t    _ = ∑ b : β, ∑ c : γ, F (some b, some c) := by\\\\n    60\\\\t        refine Finset.sum_congr rfl fun b _ => ?_\\\\n    61\\\\t        rw [h2 (some b), zero_add]\\\\n    62\\\\t    _ = ∑ bc : β × γ, F (some bc.1, some bc.2) :=\\\\n    63\\\\t        (Fintype.sum_prod_type (f := fun bc : β × γ => F (some bc.1, some bc.2))).symm\\\\n    64\\\\t\\\\n    65\\\\t/-- The completed joint measurement has the joint effect on a pair of\\\\n    66\\\\tevaluations. -/\\\\n    67\\\\ttheorem completedPair_effect_some {β γ d : Type*} [Fintype β] [Fintype γ]\\\\n    68\\\\t    [DecidableEq β] [DecidableEq γ] [Fintype d] [DecidableEq d]\\\\n    69\\\\t    (Q : Measurement (β × γ) d) (bc : β × γ) :\\\\n    70\\\\t    (Q.postprocess fun ab => (some ab.1, some ab.2)).effect (some bc.1, some bc.2) =\\\\n    71\\\\t      Q.effect bc := by\\\\n    72\\\\t  rw [MIPStarRE.Quantum.Measurement.postprocess_effect,\\\\n    73\\\\t    show (Finset.univ.filter fun cd : β × γ =>\\\\n    74\\\\t        (some cd.1, some cd.2) = (some bc.1, some bc.2)) = {bc} by\\\\n    75\\\\t      ext cd; simp [Prod.ext_iff, eq_comm]]\\\\n    76\\\\t  simp\\\\n    77\\\\t\\\\n    78\\\\t/-- The completed joint measurement vanishes on outcomes outside the image of\\\\n    79\\\\tthe completion. -/\\\\n    80\\\\ttheorem completedPair_effect_eq_zero {β γ d : Type*} [Fintype β] [Fintype γ]\\\\n    81\\\\t    [DecidableEq β] [DecidableEq γ] [Fintype d] [DecidableEq d]\\\\n    82\\\\t    (Q : Measurement (β × γ) d) (o : Option β × Option γ)\\\\n    83\\\\t    (ho : ∀ bc : β × γ, (some bc.1, some bc.2) ≠ o) :\\\\n    84\\\\t    (Q.postprocess fun ab => (some ab.1, some ab.2)).effect o = 0 := by\\\\n    85\\\\t  rw [MIPStarRE.Quantum.Measurement.postprocess_effect]\\\\n    86\\\\t  exact Finset.sum_eq_zero fun bc hbc =>\\\\n    87\\\\t    absurd (Finset.mem_filter.mp hbc).2 (ho bc)\\\\n    88\\\\t\\\\n    89\\\\t/-- The completion of a projective joint measurement is projective. -/\\\\n    90\\\\ttheorem completedPair_isProjective {β γ d : Type*} [Fintype β] [Fintype γ]\\\\n    91\\\\t    [DecidableEq β] [DecidableEq γ] [Fintype d] [DecidableEq d]\\\\n    92\\\\t    (Q : Measurement (β × γ) d) (hQ : Measurement.IsProjective Q) :\\\\n    93\\\\t    Measurement.IsProjective (Q.postprocess fun ab => (some ab.1, some ab.2)) := by\\\\n    94\\\\t  intro o\\\\n    95\\\\t  by_cases h : ∃ bc : β × γ, (some bc.1, some bc.2) = o\\\\n    96\\\\t  · obtain ⟨bc, rfl⟩ := h\\\\n    97\\\\t    rw [completedPair_effect_some]\\\\n    98\\\\t    exact hQ bc\\\\n    99\\\\t  · push Not at h\\\\n   100\\\\t    rw [completedPair_effect_eq_zero Q o h]\\\\n   101\\\\t    exact IsStarProjection.zero _\\\\n   102\\\\t\\\\n   103\\\\tnamespace ProjectiveSetting\\\\n   104\\\\t\\\\n   105\\\\tvariable {P : AdmissibleParams} {ε : ℝ}\\\\n   106\\\\t\\\\n   107\\\\t/-- A placed projection is a projection. -/\\\\n   108\\\\ttheorem place_isProj (S : ProjectiveSetting P ε) (p : Placement)\\\\n   109\\\\t    {E : Op (S.ExpandedLocalSpace p.side)} (hE : IsProj E) :\\\\n   110\\\\t    IsProj (S.place p E) := by\\\\n   111\\\\t  refine isStarProjection_iff'.2 ⟨?_, ?_⟩\\\\n   112\\\\t  · change S.place p E * S.place p E = S.place p E\\\\n   113\\\\t    rw [← place_mul, hE.isIdempotentElem.eq]\\\\n   114\\\\t  · rw [Matrix.star_eq_conjTranspose, ← place_conjTranspose,\\\\n   115\\\\t      hE.isSelfAdjoint.isHermitian.eq]\\\\n   116\\\\t\\\\n   117\\\\t/-- Every effect of the completed expanded point measurement is a projection,\\\\n   118\\\\tthe `none` effect being zero. -/\\\\n   119\\\\ttheorem pointMeasExpOption_isProj (S : ProjectiveSetting P ε)\\\\n   120\\\\t    (side : PlayerSide) (W : PauliKind) (u : Fin P.m → PauliScalar P)\\\\n   121\\\\t    (o : Option (PauliScalar P)) :\\\\n   122\\\\t    IsProj ((S.pointMeasExpOption side W u).effect o) := by\\\\n   123\\\\t  cases o with\\\\n   124\\\\t  | none =>\\\\n   125\\\\t    rw [S.pointMeasExpOption_effect_none]\\\\n   126\\\\t    exact IsStarProjection.zero _\\\\n   127\\\\t  | some a =>\\\\n   128\\\\t    rw [S.pointMeasExpOption_effect_some]\\\\n   129\\\\t    exact S.pointMeasExp_isProjective side W u a\\\\n   130\\\\t\\\\n   131\\\\t/-- The completed joint point measurement and a completed point product differ\\\\n   132\\\\tonly on outcome pairs with two evaluations, so their placed state-dependent\\\\n   133\\\\tsquared distance is the one of the joint point measurement and the point\\\\n   134\\\\tproduct.  Blueprint `ch15_qpbt_combining.tex:2651-2698`. -/\\\\n   135\\\\ttheorem sum_norm_place_completedPair_sub_sq (S : ProjectiveSetting P ε)\\\\n   136\\\\t    (p : Placement)\\\\n   137\\\\t    (Q : Measurement (PauliScalar P × PauliScalar P) (S.ExpandedLocalSpace p.side))\\\\n   138\\\\t    (Gc : Option (PauliScalar P) × Option (PauliScalar P) →\\\\n   139\\\\t      Op (S.ExpandedLocalSpace p.side))\\\\n   140\\\\t    (G : PauliScalar P × PauliScalar P → Op (S.ExpandedLocalSpace p.side))\\\\n   141\\\\t    (hsome : ∀ ab : PauliScalar P × PauliScalar P, Gc (some ab.1, some ab.2) = G ab)\\\\n   142\\\\t    (hnone1 : ∀ o2, Gc (none, o2) = 0) (hnone2 : ∀ o1, Gc (o1, none) = 0) :\\\\n   143\\\\t    (∑ o : Option (PauliScalar P) × Option (PauliScalar P),\\\\n   144\\\\t        ‖applyOperatorToState\\\\n   145\\\\t          (S.place p ((Q.postprocess fun ab => (some ab.1, some ab.2)).effect o) -\\\\n   146\\\\t            S.place p (Gc o)) S.psiHat‖ ^ 2) =\\\\n   147\\\\t      ∑ ab : PauliScalar P × PauliScalar P,\\\\n   148\\\\t        ‖applyOperatorToState (S.place p (Q.effect ab) - S.place p (G ab))\\\\n   149\\\\t          S.psiHat‖ ^ 2 := by\\\\n   150\\\\t  refine Eq.trans (sum_option_prod_eq_of_none _ ?_ ?_) ?_\\\\n   151\\\\t  · intro o2\\\\n   152\\\\t    rw [completedPair_effect_eq_zero Q (none, o2) (fun ab => by simp), hnone1,\\\\n   153\\\\t      place_zero, sub_self]\\\\n   154\\\\t    simp [applyOperatorToState]\\\\n   155\\\\t  · intro o1\\\\n   156\\\\t    rw [completedPair_effect_eq_zero Q (o1, none) (fun ab => by simp), hnone2,\\\\n   157\\\\t      place_zero, sub_self]\\\\n   158\\\\t    simp [applyOperatorToState]\\\\n   159\\\\t  · refine Finset.sum_congr rfl fun ab _ => ?_\\\\n   160\\\\t    rw [completedPair_effect_some, hsome]\\\\n   161\\\\t\\\\n   162\\\\t/-- The completed `Z`-then-`X` point product vanishes on both `none` classes\\\\n   163\\\\tand restricts to the ordered product on evaluated pairs. -/\\\\n   164\\\\ttheorem completedPair_norm_sq_sum_ZX (S : ProjectiveSetting P ε) {δ : ℝ}\\\\n   165\\\\t    (points : CombinedPointsWitness S δ) (p : Placement)\\\\n   166\\\\t    (x z : Fin P.m → PauliScalar P) :\\\\n   167\\\\t    (∑ o : Option (PauliScalar P) × Option (PauliScalar P),\\\\n   168\\\\t        ‖applyOperatorToState\\\\n   169\\\\t          (S.place p (((points.Q p.side x z).postprocess (fun ab =>\\\\n   170\\\\t              (some ab.1, some ab.2))).effect o) -\\\\n   171\\\\t            S.place p\\\\n   172\\\\t              ((S.pointMeasExpOption p.side .Z z).effect o.2 *\\\\n   173\\\\t                (S.pointMeasExpOption p.side .X x).effect o.1))\\\\n   174\\\\t          S.psiHat‖ ^ 2) =\\\\n   175\\\\t      ∑ ab : PauliScalar P × PauliScalar P,\\\\n   176\\\\t        ‖applyOperatorToState\\\\n   177\\\\t          (S.place p ((points.Q p.side x z).effect ab) -\\\\n   178\\\\t            S.place p\\\\n   179\\\\t              ((S.pointMeasExp p.side .Z z).effect ab.2 *\\\\n   180\\\\t                (S.pointMeasExp p.side .X x).effect ab.1))\\\\n   181\\\\t          S.psiHat‖ ^ 2 := by\\\\n   182\\\\t  refine S.sum_norm_place_completedPair_sub_sq p (points.Q p.side x z) _ _ ?_ ?_ ?_\\\\n   183\\\\t  · intro ab\\\\n   184\\\\t    rw [S.pointMeasExpOption_effect_some, S.pointMeasExpOption_effect_some]\\\\n   185\\\\t  · intro o2\\\\n   186\\\\t    rw [S.pointMeasExpOption_effect_none, mul_zero]\\\\n   187\\\\t  · intro o1\\\\n   188\\\\t    rw [S.pointMeasExpOption_effect_none, zero_mul]\\\\n   189\\\\t\\\\n   190\\\\t\\\\n   191\\\\tend ProjectiveSetting\\\\n   192\\\\t\\\\n   193\\\\t/-! ## The abstract one-point deficit -/\\\\n   194\\\\t\\\\n   195\\\\t/-- Let `A` be a complete measurement, `Q` a projective measurement, `R` a\\\\n   196\\\\tfamily of projections and `W` a family of operators, all indexed by the same\\\\n   197\\\\toutcomes, with `Q`, `R` and `W` commuting with the effects of `A` and with\\\\n   198\\\\t`W R = W`.  If `A` and `Q` are consistent with defect at most `η` and `Q` is\\\\n   199\\\\twithin squared distance `ζ` of `Wᴴ`, then the deficit of the overlap of `A`\\\\n   200\\\\twith `R` is at most `2 √η + 2 √ζ`.  The proof inserts `Q` before `R`, replaces\\\\n   201\\\\t`Q R` by `W R = W`, and compares `W` with `Q`; each of the three steps is a\\\\n   202\\\\tCauchy--Schwarz estimate weighted by `A`.  This is the common estimate behind\\\\n   203\\\\tthe deficits in the proofs of `lem:claim-17-2` and `lem:claim-17-3`, paper\\\\n   204\\\\t`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1168-1239`. -/\\\\n   205\\\\ttheorem one_sub_overlap_le_of_consistencyDefect {X α ι : Type*}\\\\n   206\\\\t    [Fintype X] [DecidableEq X] [Fintype α] [DecidableEq α]\\\\n   207\\\\t    [Fintype ι] [DecidableEq ι]\\\\n   208\\\\t    (μ : Distribution X) (A Q : X → Measurement α ι) (R W : X → α → Op ι)\\\\n   209\\\\t    (ψ : EuclideanSpace ℂ ι) (hμ : μ.IsProbability) (hψ : ‖ψ‖ = 1)\\\\n   210\\\\t    (hQ : ∀ x, Measurement.IsProjective (Q x)) (hR : ∀ x a, IsProj (R x a))\\\\n   211\\\\t    (hAQ : ∀ x a, Commute ((A x).effect a) ((Q x).effect a))\\\\n   212\\\\t    (hAR : ∀ x a, Commute ((A x).effect a) (R x a))\\\\n   213\\\\t    (hAW : ∀ x a, Commute ((A x).effect a) (W x a))\\\\n   214\\\\t    (hWR : ∀ x a, W x a * R x a = W x a)\\\\n   215\\\\t    (hnonneg : ∀ x a, 0 ≤ stateQForm ψ ((A x).effect a * (Q x).effect a))\\\\n   216\\\\t    (η ζ : ℝ)\\\\n   217\\\\t    (hcons : consistencyDefect μ (fun x a => (A x).effect a)\\\\n   218\\\\t      (fun x a => (Q x).effect a) ψ ≤ η)\\\\n   219\\\\t    (hdist : opFamilyDistSq μ (fun x a => (Q x).effect a)\\\\n   220\\\\t      (fun x a => (W x a)ᴴ) ψ ≤ ζ) :\\\\n   221\\\\t    1 - avgOver μ (fun x => ∑ a, stateQForm ψ ((A x).effect a * R x a)) ≤\\\\n   222\\\\t      2 * Real.sqrt η + 2 * Real.sqrt ζ := by\\\\n   223\\\\t  set ovQ := avgOver μ (fun x =>\\\\n   224\\\\t    ∑ a, stateQForm ψ ((A x).effect a * (Q x).effect a)) with hovQ\\\\n   225\\\\t  have h1 : 1 - ovQ ≤ η := by\\\\n   226\\\\t    rw [← consistencyDefect_eq_one_sub_overlap μ A Q ψ hμ hψ]\\\\n   227\\\\t    exact hcons\\\\n   228\\\\t  have hovQ_nonneg : 0 ≤ ovQ :=\\\\n   229\\\\t    avgOver_nonneg μ _ fun x => Finset.sum_nonneg fun a _ => hnonneg x a\\\\n   230\\\\t  have hovQ_le : ovQ ≤ 1 :=\\\\n   231\\\\t    avgOver_sum_stateQForm_mul_le_one μ A (fun x a => (Q x).effect a) ψ hμ hψ\\\\n   232\\\\t      (fun x a => hQ x a) hAQ\\\\n   233\\\\t  have h1' : 1 - ovQ ≤ Real.sqrt η := by\\\\n   234\\\\t    have h0 : 0 ≤ 1 - ovQ := by linarith\\\\n   235\\\\t    calc 1 - ovQ = Real.sqrt ((1 - ovQ) ^ 2) := (Real.sqrt_sq h0).symm\\\\n   236\\\\t      _ ≤ Real.sqrt η := Real.sqrt_le_sqrt (by nlinarith)\\\\n   237\\\\t  -- comparing `Q` with `W` under the weight `A`\\\\n   238\\\\t  have hWconj : ∀ x a, stateQForm ψ ((A x).effect a * W x a) =\\\\n   239\\\\t      stateQForm ψ ((A x).effect a * (W x a)ᴴ) := by\\\\n   240\\\\t    intro x a\\\\n   241\\\\t    rw [← stateQForm_conjTranspose ψ ((A x).effect a * W x a),\\\\n   242\\\\t      Matrix.conjTranspose_mul, measurement_effect_hermitian]\\\\n   243\\\\t    congr 1\\\\n   244\\\\t    have h := congrArg Matrix.conjTranspose (hAW x a).eq\\\\n   245\\\\t    rw [Matrix.conjTranspose_mul, Matrix.conjTranspose_mul,\\\\n   246\\\\t      measurement_effect_hermitian] at h\\\\n   247\\\\t    exact h\\\\n   248\\\\t  have h2 : |ovQ - avgOver μ (fun x =>\\\\n   249\\\\t      ∑ a, stateQForm ψ ((A x).effect a * W x a))| ≤ Real.sqrt ζ := by\\\\n   250\\\\t    rw [avgOver_congr μ _ _ fun x => Finset.sum_congr rfl fun a _ => hWconj x a]\\\\n   251\\\\t    exact abs_overlap_gap_le_sqrt_of_opFamilyDistSq μ A\\\\n   252\\\\t      (fun x a => (Q x).effect a) (fun x a => (W x a)ᴴ) ψ hμ hψ ζ hdist\\\\n   253\\\\t  -- replacing `Q R` by `W R = W`\\\\n   254\\\\t  have h4 : |avgOver μ (fun x =>\\\\n   255\\\\t      ∑ a, stateQForm ψ ((A x).effect a * ((Q x).effect a * R x a))) -\\\\n   256\\\\t        avgOver μ (fun x => ∑ a, stateQForm ψ ((A x).effect a * W x a))| ≤\\\\n   257\\\\t      Real.sqrt ζ := by\\\\n   258\\\\t    have hpt : ∀ x,\\\\n   259\\\\t        (∑ a, stateQForm ψ ((A x).effect a * ((Q x).effect a * R x a))) -\\\\n   260\\\\t          (∑ a, stateQForm ψ ((A x).effect a * W x a)) =\\\\n   261\\\\t        ∑ a, stateQForm ψ ((A x).effect a * (((Q x).effect a - W x a) * R x a)) := by\\\\n   262\\\\t      intro x\\\\n   263\\\\t      rw [← Finset.sum_sub_distrib]\\\\n   264\\\\t      refine Finset.sum_congr rfl fun a _ => ?_\\\\n   265\\\\t      rw [sub_mul, hWR]\\\\n   266\\\\t      simp [stateQForm, applyOperatorToState, mul_sub]\\\\n   267\\\\t    rw [← avgOver_sub, avgOver_congr μ _ _ hpt]\\\\n   268\\\\t    have hcs := abs_avgOver_sum_stateQForm_mul_le_sqrt_of_isProj' μ A\\\\n   269\\\\t      (fun x a => (Q x).effect a - W x a) R ψ hμ hψ hR hAR\\\\n   270\\\\t      (fun x a => (hAQ x a).sub_right (hAW x a))\\\\n   271\\\\t    refine hcs.trans (Real.sqrt_le_sqrt ?_)\\\\n   272\\\\t    have hdist' : avgOver μ (fun x =>\\\\n   273\\\\t        ∑ a, ‖applyOperatorToState ((Q x).effect a - (W x a)ᴴ) ψ‖ ^ 2) ≤ ζ :=\\\\n   274\\\\t      hdist\\\\n   275\\\\t    refine le_of_eq_of_le ?_ hdist'\\\\n   276\\\\t    refine avgOver_congr μ _ _ fun x => Finset.sum_congr rfl fun a _ => ?_\\\\n   277\\\\t    rw [Matrix.conjTranspose_sub, measurement_effect_hermitian]\\\\n   278\\\\t  -- inserting `Q` before `R`\\\\n   279\\\\t  have h5 : |avgOver μ (fun x =>\\\\n   280\\\\t      ∑ a, stateQForm ψ ((A x).effect a * ((Q x).effect a * R x a))) -\\\\n   281\\\\t        avgOver μ (fun x => ∑ a, stateQForm ψ ((A x).effect a * R x a))| ≤\\\\n   282\\\\t      Real.sqrt η := by\\\\n   283\\\\t    have hpt : ∀ x,\\\\n   284\\\\t        (∑ a, stateQForm ψ ((A x).effect a * R x a)) -\\\\n   285\\\\t          (∑ a, stateQForm ψ ((A x).effect a * ((Q x).effect a * R x a))) =\\\\n   286\\\\t        ∑ a, stateQForm ψ ((A x).effect a * ((1 - (Q x).effect a) * R x a)) := by\\\\n   287\\\\t      intro x\\\\n   288\\\\t      rw [← Finset.sum_sub_distrib]\\\\n   289\\\\t      refine Finset.sum_congr rfl fun a _ => ?_\\\\n   290\\\\t      simp [stateQForm, applyOperatorToState, sub_mul, mul_sub]\\\\n   291\\\\t    rw [abs_sub_comm, ← avgOver_sub, avgOver_congr μ _ _ hpt]\\\\n   292\\\\t    have hcs := abs_avgOver_sum_stateQForm_mul_mul_le_sqrt_mul_sqrt μ A\\\\n   293\\\\t      (fun x a => 1 - (Q x).effect a) R ψ (fun x a => (hQ x a).one_sub)\\\\n   294\\\\t      (fun x a => (Commute.one_right _).sub_right (hAQ x a))\\\\n   295\\\\t    have hfirst : avgOver μ (fun x =>\\\\n   296\\\\t        ∑ a, stateQForm ψ ((A x).effect a * (1 - (Q x).effect a))) = 1 - ovQ := by\\\\n   297\\\\t      have hx : ∀ x,\\\\n   298\\\\t          (∑ a, stateQForm ψ ((A x).effect a * (1 - (Q x).effect a))) =\\\\n   299\\\\t            1 - ∑ a, stateQForm ψ ((A x).effect a * (Q x).effect a) := by\\\\n   300\\\\t        intro x\\\\n   301\\\\t        rw [← sum_stateQForm_effect_eq_one (A x) ψ hψ, ← Finset.sum_sub_distrib]\\\\n   302\\\\t        refine Finset.sum_congr rfl fun a _ => ?_\\\\n   303\\\\t        simp [stateQForm, applyOperatorToState, mul_sub]\\\\n   304\\\\t      rw [avgOver_congr μ _ _ hx, avgOver_sub, avgOver_const_of_isProbability μ hμ]\\\\n   305\\\\t    have hsecond : avgOver μ (fun x =>\\\\n   306\\\\t        ∑ a, stateQForm (applyOperatorToState (R x a) ψ) ((A x).effect a)) ≤ 1 := by\\\\n   307\\\\t      rw [avgOver_congr μ _ _ fun x => Finset.sum_congr rfl fun a _ =>\\\\n   308\\\\t        stateQForm_applyOperatorToState_eq_of_isProj ψ (hR x a) (hAR x a)]\\\\n   309\\\\t      exact avgOver_sum_stateQForm_mul_le_one μ A R ψ hμ hψ hR hAR\\\\n   310\\\\t    rw [hfirst] at hcs\\\\n   311\\\\t    calc\\\\n   312\\\\t      _ ≤ _ := hcs\\\\n   313\\\\t      _ ≤ Real.sqrt (1 - ovQ) * 1 := by\\\\n   314\\\\t        refine mul_le_mul_of_nonneg_left ?_ (Real.sqrt_nonneg _)\\\\n   315\\\\t        rw [← Real.sqrt_one]\\\\n   316\\\\t        exact Real.sqrt_le_sqrt hsecond\\\\n   317\\\\t      _ = Real.sqrt (1 - ovQ) := mul_one _\\\\n   318\\\\t      _ ≤ Real.sqrt η := Real.sqrt_le_sqrt h1\\\\n   319\\\\t  have h2' := abs_le.mp h2\\\\n   320\\\\t  have h4' := abs_le.mp h4\\\\n   321\\\\t  have h5' := abs_le.mp h5\\\\n   322\\\\t  linarith [h2'.1, h4'.1, h5'.1, h2'.2, h4'.2, h5'.2]\\\\n   323\\\\t\\\\n   324\\\\t/-! ## The two placed deficits -/\\\\n   325\\\\t\\\\n   326\\\\t/-- A pair of line-point pairs of the source space: the sample type of the\\\\n   327\\\\tconsistency display of `lem:qld-xz-lines`. -/\\\\n   328\\\\tabbrev LinePointPairSample (P : AdmissibleParams) :=\\\\n   329\\\\t  (LineDesc P.toLdParams × (Fin P.m → PauliScalar P)) ×\\\\n   330\\\\t    (LineDesc P.toLdParams × (Fin P.m → PauliScalar P))\\\\n   331\\\\t\\\\n   332\\\\tsection Placed\\\\n   333\\\\t\\\\n   334\\\\tvariable {P : AdmissibleParams} {ε δQ δP : ℝ} {S : ProjectiveSetting P ε}\\\\n   335\\\\t  {points : CombinedPointsWitness S δQ}\\\\n   336\\\\t\\\\n   337\\\\t/-- The `Z`-point deficit of the evaluated pair-line measurement over a\\\\n   338\\\\tprobability law on pairs of line-point pairs, from the consistency of the\\\\n   339\\\\tevaluated pair-line measurement with the completed joint point measurement\\\\n   340\\\\tand the closeness of the latter to the `Z`-then-`X` product.  This is the\\\\n   341\\\\tdeficit bounded in the proof of `lem:claim-17-3`, paper\\\\n   342\\\\t`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1204-1239`. -/\\\\n   343\\\\ttheorem CombinedLinesWitness.one_sub_Z_overlap_le_at\\\\n   344\\\\t    (lines : CombinedLinesWitness S points δP)\\\\n   345\\\\t    (first second : Placement) (hopposite : first.IsOpposite second)\\\\n   346\\\\t    (ν : Distribution (LinePointPairSample P)) (hν : ν.IsProbability) (η ζ : ℝ)\\\\n   347\\\\t    (hcons : consistencyDefect ν\\\\n   348\\\\t      (fun s o => S.place first\\\\n   349\\\\t        (((lines.T first.side s.1.1 s.2.1).post