\t    fun s o => S.place_isProj _ (S.pointMeasExpOption_isProj _ _ _ _)\\\\n   380\\\\t  have hWR : ∀ (s : LinePointPairSample P)\\\\n   381\\\\t      (o : Option (PauliScalar P) × Option (PauliScalar P)),\\\\n   382\\\\t      S.place second ((S.pointMeasExpOption second.side .X s.1.2).effect o.1 *\\\\n   383\\\\t          (S.pointMeasExpOption second.side .Z s.2.2).effect o.2) *\\\\n   384\\\\t        S.place second ((S.pointMeasExpOption second.side .Z s.2.2).effect o.2) =\\\\n   385\\\\t      S.place second ((S.pointMeasExpOption second.side .X s.1.2).effect o.1 *\\\\n   386\\\\t        (S.pointMeasExpOption second.side .Z s.2.2).effect o.2) := by\\\\n   387\\\\t    intro s o\\\\n   388\\\\t    have hlocal : (S.pointMeasExpOption second.side .X s.1.2).effect o.1 *\\\\n   389\\\\t          (S.pointMeasExpOption second.side .Z s.2.2).effect o.2 *\\\\n   390\\\\t        (S.pointMeasExpOption second.side .Z s.2.2).effect o.2 =\\\\n   391\\\\t        (S.pointMeasExpOption second.side .X s.1.2).effect o.1 *\\\\n   392\\\\t          (S.pointMeasExpOption second.side .Z s.2.2).effect o.2 := by\\\\n   393\\\\t      rw [mul_assoc, (S.pointMeasExpOption_isProj second.side .Z s.2.2 o.2).isIdempotentElem.eq]\\\\n   394\\\\t    exact (ProjectiveSetting.place_mul S second _ _).symm.trans\\\\n   395\\\\t      (congrArg (S.place second) hlocal)\\\\n   396\\\\t  have hnonneg : ∀ (s : LinePointPairSample P)\\\\n   397\\\\t      (o : Option (PauliScalar P) × Option (PauliScalar P)),\\\\n   398\\\\t      0 ≤ stateQForm S.psiHat\\\\n   399\\\\t        (S.place first\\\\n   400\\\\t          (((lines.T first.side s.1.1 s.2.1).postprocess fun fs =>\\\\n   401\\\\t            (evalOpt s.1.1 s.1.2 fs.1, evalOpt s.2.1 s.2.2 fs.2)).effect o) *\\\\n   402\\\\t          S.place second\\\\n   403\\\\t            (((points.Q second.side s.1.2 s.2.2).postprocess fun ab =>\\\\n   404\\\\t              (some ab.1, some ab.2)).effect o)) :=\\\\n   405\\\\t    fun s o => stateQForm_nonneg _ (S.place