g points deltaL) +    (kind : LdType) (sample : DirectLdSpace P.extendedDirectLd) +    (readLine : DirectLdAnswer P.extendedDirectLd → Option (PauliScalar P)) : +    outcomeEventWeight (strategy lines) +        (kind, directLdMap P.extendedDirectLd kind sample) +        (.point, directLdMap P.extendedDirectLd .point sample) +        (fun answerA _ => readLine answerA = none) = +      outcomeEventWeight (strategy lines) +        (kind, directLdMap P.extendedDirectLd kind sample) +        (.point, directLdMap P.extendedDirectLd .point sample) +        (fun answerA answerB => +          readLine answerA = none ∧ pointGameRead answerB ≠ none) := by +  classical +  unfold outcomeEventWeight +  apply Finset.sum_congr rfl +  intro answerA _ +  apply Finset.sum_congr rfl +  intro answerB _ +  by_cases hline : readLine answerA = none +  · by_cases hpoint : pointGameRead answerB = none +    · have hinvalid := (pointGameRead_eq_none_iff_invalid answerB).1 hpoint +      rw [outcomeWeight_eq_zero_of_invalid lines _ _ answerA answerB (Or.inr hinvalid)] +      simp [hline, hpoint] +    · simp [hline, hpoint] +  · simp [hline] + +/-- After zero-weight invalid point answers are removed, Bob's line-`none` +event is the event that the point read is not `none` and the line read is. -/ +private theorem bob_line_none_event_eq_point_some +    (lines : ExtendedLinesWitness setting points deltaL) +    (kind : LdType) (sample : DirectLdSpace P.extendedDirectLd) +    (readLine : DirectLdAnswer P.extendedDirectLd → Option (PauliScalar P)) : +    outcomeEventWeight (strategy lines) +        (.point, directLdMap P.extendedDirectLd .point sample) +        (kind, directLdMap P.extendedDirectLd kind sample) +        (fun _ answerB => readLine answerB = none) = +      outcomeEventWeight (strategy lines) +        (.point, directLdMap P.extendedDirectLd .point sample) +        (kind, directLdMap P.extendedDirectLd kind sample) +        (fun answerA answerB => +          pointGameRead answerA ≠ none ∧ 